public class HelloController {
    @Route("/")
    public void home(Req q, Res s) { s.text("첫 화면\n"); }

    @Route("/hello")
    public void hello(Req q, Res s) {
        String n = q.param("name");
        s.text("안녕하세요 " + (n == null ? "손님" : n) + "\n");
    }

    @Route(value = "/echo", method = "POST")
    public void echo(Req q, Res s) { s.text("받았다: " + q.bodyText() + "\n"); }

    public void notARoute(Req q, Res s) { s.text("등록되지 않는다\n"); }
}

try (var st = Files.walk(dir)) {
    st.filter(p -> p.toString().endsWith(".class")).forEach(p -> {
        String rel = dir.relativize(p).toString();
        names.add(rel.substring(0, rel.length() - 6)      // ".class" 를 떼고
                     .replace(File.separatorChar, '.'));   // / 를 . 으로
    });
}

for (String n : names) {
    Class<?> c;
    try { c = Class.forName(n); } catch (Throwable e) { continue; }
    for (Method m : c.getDeclaredMethods()) {          // 10.3절
        Route r = m.getAnnotation(Route.class);        // 11.3절
        if (r == null) continue;
        String key = r.method() + " " + r.value();
        Object bean = beans.computeIfAbsent(c.getName(),
            k -> c.getDeclaredConstructor().newInstance());   // 10.5절
        m.setAccessible(true);                                // 10.4절
        routes.put(key, new Handler(bean, m));
    }
}
